// Generated by GitHub Copilot
const fs = require("node:fs");
const path = require("node:path");
const os = require("node:os");
const { spawn } = require("node:child_process");
const { app } = require("electron");
const { hasRuntimeLibraries } = require("./whisper-cli-installer.cjs");
const { resolveFfmpegPath } = require("./ffmpeg-installer.cjs");

// 0xC0000135 no Windows: processo nao iniciou por DLL ausente ao lado do executavel.
const STATUS_DLL_NOT_FOUND = 3221225781;

/**
 * Cria manager do whisper-cli para transcricao local por execucao isolada.
 */
function createWhisperCliManager(options) {
  const logger = options?.logger || {
    info: () => {},
    warn: () => {},
    error: () => {}
  };
  const configuredPath = options?.binaryPath || process.env.WHISPER_CLI_PATH || "";
  const configuredModel = options?.modelPath || process.env.WHISPER_MODEL_PATH || "";
  const modelManager = options?.modelManager;
  const settingsStore = options?.settingsStore;
  const defaultBinaryName = process.platform === "win32" ? "whisper-cli.exe" : "whisper-cli";

  let status = "idle";
  let lastError = "";
  let lastRunAtIso = "";

  function resolveBinaryPath() {
    const candidates = [
      configuredPath,
      path.join(app.getPath("userData"), "runtime", "whisper", defaultBinaryName),
      path.join(app.getPath("userData"), "runtime", defaultBinaryName),
      path.join(process.cwd(), "bin", defaultBinaryName)
    ].filter(Boolean);

    const complete = candidates.find(
      (candidate) => fs.existsSync(candidate) && hasRuntimeLibraries(candidate)
    );
    return complete || "";
  }

  function resolveModelPath() {
    if (configuredModel && fs.existsSync(configuredModel)) {
      return configuredModel;
    }

    if (modelManager) {
      const preferred = settingsStore?.getTranscriptionPacks?.()?.preferredModelTier;
      if (preferred === "medium") {
        const medium = modelManager.resolveModelPath("whisper-medium");
        if (medium) {
          return medium;
        }
      }
      if (preferred === "small") {
        const small = modelManager.resolveModelPath("whisper-small");
        if (small) {
          return small;
        }
      }
      const base = modelManager.resolveModelPath("whisper");
      if (base) {
        return base;
      }
      const smallFallback = modelManager.resolveModelPath("whisper-small");
      if (smallFallback) {
        return smallFallback;
      }
      const mediumFallback = modelManager.resolveModelPath("whisper-medium");
      if (mediumFallback) {
        return mediumFallback;
      }
    }

    const localModel = path.join(app.getPath("userData"), "runtime", "models", "ggml-base.bin");
    if (fs.existsSync(localModel)) {
      return localModel;
    }

    const localSmall = path.join(app.getPath("userData"), "runtime", "models", "ggml-small.bin");
    if (fs.existsSync(localSmall)) {
      return localSmall;
    }

    return "";
  }

  function getStatus() {
    return {
      state: status,
      binaryPath: resolveBinaryPath(),
      modelPath: resolveModelPath(),
      lastRunAtIso,
      lastError
    };
  }

  async function ensureAvailable() {
    const binaryPath = resolveBinaryPath();
    let modelPath = resolveModelPath();

    if (!binaryPath) {
      status = "unavailable";
      lastError =
        "Binario whisper-cli (com as DLLs do runtime) nao encontrado. Reinstale o runtime em Configuracoes > Traducao ou defina WHISPER_CLI_PATH.";
      logger.warn("whisper-cli unavailable", { lastError });
      return getStatus();
    }

    if (!modelPath) {
      if (modelManager) {
        const ensured = await modelManager.ensureModel("whisper");
        if (ensured.state === "ready") {
          modelPath = ensured.filePath;
        }
      }

      if (!modelPath) {
        status = "unavailable";
        lastError = "Modelo Whisper nao encontrado. Defina WHISPER_MODEL_PATH ou configure download via ModelManager.";
        logger.warn("whisper model unavailable", { lastError });
        return getStatus();
      }
    }

    status = "ready";
    return getStatus();
  }

  function getTempDir() {
    const tempDir = path.join(os.tmpdir(), "clone-perssua-stt");
    if (!fs.existsSync(tempDir)) {
      fs.mkdirSync(tempDir, { recursive: true });
    }
    return tempDir;
  }

  function isWavBuffer(buffer) {
    return (
      buffer.length > 12 &&
      buffer.toString("ascii", 0, 4) === "RIFF" &&
      buffer.toString("ascii", 8, 12) === "WAVE"
    );
  }

  function writeChunkToTempFile(chunkBase64) {
    const buffer = Buffer.from(chunkBase64 || "", "base64");
    const extension = isWavBuffer(buffer) ? "wav" : "webm";
    const filePath = path.join(
      getTempDir(),
      `chunk-${Date.now()}-${Math.random().toString(16).slice(2)}.${extension}`
    );
    fs.writeFileSync(filePath, buffer);
    return { filePath, isWav: extension === "wav" };
  }

  /** whisper-cli so aceita WAV PCM 16 bits mono a 16 kHz. */
  function convertToWhisperWav(inputPath) {
    const outputPath = `${inputPath}.16k.wav`;
    return new Promise((resolve, reject) => {
      const proc = spawn(
        resolveFfmpegPath(),
        [
          "-hide_banner",
          "-loglevel",
          "error",
          "-i",
          inputPath,
          "-ac",
          "1",
          "-ar",
          "16000",
          "-c:a",
          "pcm_s16le",
          "-y",
          outputPath
        ],
        { windowsHide: true }
      );
      let stderr = "";
      proc.stderr.on("data", (chunk) => {
        stderr += String(chunk || "");
      });
      proc.on("error", (error) =>
        reject(
          new Error(
            `ffmpeg indisponivel para converter o audio (${error.message}). Instale o ffmpeg em Configuracoes > Traducao.`
          )
        )
      );
      proc.on("close", (code) => {
        if (code === 0 && fs.existsSync(outputPath)) {
          resolve(outputPath);
          return;
        }
        reject(new Error(stderr.trim() || `ffmpeg falhou ao converter audio (codigo ${code}).`));
      });
    });
  }

  function parseWhisperOutput(stdoutText) {
    const normalized = (stdoutText || "").trim();
    if (!normalized) {
      return "";
    }

    const lines = normalized
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean)
      .filter((line) => !line.startsWith("[") || line.includes("] "));

    return lines.join(" ").trim();
  }

  function cleanupFiles(filePaths) {
    for (const filePath of filePaths) {
      try {
        fs.unlinkSync(filePath);
      } catch {
        // arquivo temporario pode ja ter sido removido
      }
    }
  }

  function describeExitFailure(code, stderr, binaryPath) {
    if (code === STATUS_DLL_NOT_FOUND) {
      return `whisper-cli nao iniciou: DLLs do runtime ausentes ao lado de ${binaryPath} (codigo ${code}). Reinstale o runtime de transcricao em Configuracoes > Traducao.`;
    }
    return stderr.trim() || `whisper-cli exited with code ${code}`;
  }

  async function transcribeChunk(params) {
    const availability = await ensureAvailable();
    if (availability.state !== "ready") {
      throw new Error(availability.lastError || "Runtime Whisper indisponivel.");
    }

    const written = writeChunkToTempFile(params.chunkBase64 || "");
    const tempFiles = [written.filePath];
    let audioPath = written.filePath;

    try {
      audioPath = await convertToWhisperWav(written.filePath);
      tempFiles.push(audioPath);
    } catch (error) {
      if (!written.isWav) {
        cleanupFiles(tempFiles);
        status = "error";
        lastError = error instanceof Error ? error.message : String(error);
        throw new Error(lastError);
      }
    }

    const binaryPath = availability.binaryPath;
    const modelPath = availability.modelPath;
    const language = params.language || "auto";

    status = "running";
    lastError = "";
    lastRunAtIso = new Date().toISOString();

    return new Promise((resolve, reject) => {
      const args = ["-m", modelPath, "-f", audioPath, "-otxt"];
      if (language !== "auto") {
        args.push("-l", language);
      }

      const child = spawn(binaryPath, args, {
        cwd: path.dirname(binaryPath),
        stdio: ["ignore", "pipe", "pipe"],
        windowsHide: true
      });

      let stdout = "";
      let stderr = "";

      child.stdout.on("data", (chunk) => {
        stdout += String(chunk || "");
      });

      child.stderr.on("data", (chunk) => {
        stderr += String(chunk || "");
      });

      child.on("error", (error) => {
        status = "error";
        lastError = error.message;
        cleanupFiles(tempFiles);
        reject(error);
      });

      child.on("close", (code) => {
        status = code === 0 ? "ready" : "error";
        cleanupFiles(tempFiles);

        if (code !== 0) {
          lastError = describeExitFailure(code, stderr, binaryPath);
          logger.warn("whisper-cli run failed", { code, binaryPath, lastError });
          reject(new Error(lastError));
          return;
        }

        const text = parseWhisperOutput(stdout);
        resolve({
          text,
          isFinal: true
        });
      });
    });
  }

  function stop() {
    status = status === "running" ? "ready" : status;
    return getStatus();
  }

  return {
    ensureAvailable,
    getStatus,
    transcribeChunk,
    stop
  };
}

module.exports = {
  createWhisperCliManager
};
